using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
public static class VerifyNativeCSL {
 public static void Run(){try{Check();Debug.Log("NATIVE_CSL_RENDER_VERIFIED");EditorApplication.Exit(0);}catch(Exception e){Debug.LogError("NATIVE_CSL_RENDER_FAILED "+e);EditorApplication.Exit(1);}}
 static void Check(){
 var args=Environment.GetCommandLineArgs();string path=args[Array.IndexOf(args,"-workshopBundle")+1];var bundle=AssetBundle.LoadFromFile(path);if(!bundle)throw new Exception("Bundle rejected");
 var prefab=bundle.LoadAsset<GameObject>("_CustomSaber");if(!prefab||!prefab.GetComponent<SaberDescriptor>())throw new Exception("Descriptor not recognized");
 var root=UnityEngine.Object.Instantiate(prefab);if(root.GetComponentsInChildren<MonoBehaviour>(true).Any(x=>!x))throw new Exception("Missing script");
 int countIndex=Array.IndexOf(args,"-expectedMeshes");int expected=countIndex<0?10:int.Parse(args[countIndex+1]);if(root.GetComponentsInChildren<MeshRenderer>().Length!=expected)throw new Exception("Unexpected mesh count");
 bool studioTest=Array.IndexOf(args,"-verifyStudio")>=0;if(studioTest){var particles=root.GetComponentsInChildren<ParticleSystem>();if(particles.Length!=2)throw new Exception("Particle emitters missing from export");foreach(var system in particles){system.Simulate(.5f,true,true,true);if(system.particleCount<1||Math.Abs(system.emission.rateOverTime.constant-60)>.01f||Math.Abs(system.main.startSize.constant-.008f)>.0001f)throw new Exception("Exported particle settings lost");var material=system.GetComponent<ParticleSystemRenderer>().sharedMaterial;if(!material||material.shader.name!="Workshop/Particle"||!material.shader.isSupported)throw new Exception("Exported particle shader missing");}foreach(var r in root.GetComponentsInChildren<MeshRenderer>())if(r.sharedMaterial.shader.name!="Workshop/Effect"||!r.sharedMaterial.shader.isSupported||r.sharedMaterial.GetVector("_BoundsSize").z<1)throw new Exception("Exported volume material lost");var trails=root.GetComponentsInChildren<TrailRenderer>();if(trails.Length!=2||trails.Any(t=>Math.Abs(t.widthMultiplier-.12f)>.0001f||Math.Abs(t.time-.27f)>.0001f||!t.sharedMaterial.shader.isSupported||t.sharedMaterial.shader.name!="Workshop/Trail"))throw new Exception("Exported trails lost settings or material");Debug.Log("NATIVE_STUDIO_VERIFIED particle emitters="+particles.Length+" trails="+trails.Length);}
 bool outlineTest=Array.IndexOf(args,"-verifyOutline")>=0;if(outlineTest)foreach(var r in root.GetComponentsInChildren<MeshRenderer>())r.sharedMaterial.SetColor("_Color",r.name.Contains("outline")?Color.white:Color.red);
 foreach(var filter in root.GetComponentsInChildren<MeshFilter>()){var mesh=filter.sharedMesh;if(mesh.vertexCount==0||mesh.triangles.Any(i=>i<0||i>=mesh.vertexCount))throw new Exception("Invalid mesh");}
 root.transform.rotation=Quaternion.Euler(-90,0,0);root.transform.Find("LeftSaber").localPosition=new Vector3(-.12f,0,0);root.transform.Find("RightSaber").localPosition=new Vector3(.12f,0,0);
 var camera=new GameObject("Render verification").AddComponent<Camera>();camera.transform.position=new Vector3(0,.4f,-2);camera.orthographic=true;camera.orthographicSize=.8f;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;
 var rt=new RenderTexture(outlineTest?1024:256,outlineTest?2048:512,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var image=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();File.WriteAllBytes(Path.Combine(Path.GetDirectoryName(path),"Flux-render.png"),image.EncodeToPNG());int lit=image.GetPixels().Count(c=>Mathf.Max(c.r,Mathf.Max(c.g,c.b))>.05f);if(lit<100)throw new Exception("Blank render: "+lit);if(outlineTest){int white=image.GetPixels().Count(c=>c.r>.8f&&c.g>.8f&&c.b>.8f);int red=image.GetPixels().Count(c=>c.r>.8f&&c.g<.1f&&c.b<.1f);if(white<10||red<100)throw new Exception("Outline does not form a visible rim: white="+white+" red="+red);Debug.Log("Outline rim pixels="+white+" body pixels="+red);}
 Debug.Log("Native bundle rendered pixels="+lit);File.WriteAllBytes(Path.Combine(Path.GetDirectoryName(path),"Flux-render.png"),image.EncodeToPNG());
 RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(camera.gameObject);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(root);bundle.Unload(true);
 }
}
